<h1>What this building would mean for the block</h1>
<p>Move the sliders. The notes below tell you what a neighbor would notice.</p>

<div class="ctrl"><label>How tall: <output id="hV"></output></label>
<input type="range" id="h" min="3" max="40" value="12"></div>

<div class="ctrl"><label>How many homes: <output id="uV"></output></label>
<input type="range" id="u" min="10" max="400" value="120"></div>

<div class="ctrl"><label>Parking spots per home: <output id="pV"></output></label>
<input type="range" id="p" min="0" max="2" step="0.25" value="1"></div>

<div class="ctrl"><label>Share kept as open ground: <output id="oV"></output></label>
<input type="range" id="o" min="0" max="60" value="15"></div>

<div class="out" id="out"></div>

<script>
const $=id=>document.getElementById(id);
function upd(){
